"""Three clans, six source-specific versions. Original page images reviewed."""
import json,sys
from pathlib import Path
repo=Path(__file__).resolve().parent.parent;work=Path(sys.argv[1]);sources=json.loads((work/'pages/manifest.json').read_text(encoding='utf-8'))
def version(id,book,pages,title,disc,disc_en,bane,bane_en,comp,comp_en,extra='',extra_en=''):
 sections={}
 for locale,ds,b,c,note in [('pt-BR',disc,bane,comp,extra),('en',disc_en,bane_en,comp_en,extra_en)]:
  values=[{'title':'Disciplinas de Clã' if locale=='pt-BR' else 'Clan Disciplines','text':ds},{'title':'Perdição (Fraqueza)' if locale=='pt-BR' else 'Bane','text':b},{'title':'Compulsão do Clã' if locale=='pt-BR' else 'Clan Compulsion','text':c}]
  if note:values.append({'title':'Exceções e versões' if locale=='pt-BR' else 'Exceptions and versions','text':note})
  values.append({'title':'Uso e fonte' if locale=='pt-BR' else 'Use and source','text':'A Gravidade da Perdição depende da Potência de Sangue. Esta consulta apresenta a regra da fonte selecionada; não aplica penalidades automaticamente nem modifica textos pessoais da ficha. História e arquétipos continuam na biblioteca. Os poderes têm descrições próprias.' if locale=='pt-BR' else 'Bane Severity depends on Blood Potency. This reference presents the selected source’s rule; it does not automatically apply penalties or alter personal sheet text. History and archetypes remain in the library. Powers have their own descriptions.'})
  sections[locale]=values
 return {'id':id,'book':book,'sourceTitle':title,'sourceLanguage':'en' if book=='players-guide-v5' else 'pt-BR','pdfSha256':next(source['sha256'] for source in sources if source['id']==book),'pages':[{'pdfPage':pdf,'printedPage':printed} for pdf,printed in pages],'descriptions':sections}
def add(slug,pt,en,aliases,versions):
 entry={'id':'clan-'+slug,'kind':'clan','names':{'pt-BR':pt,'en':en},'aliases':list(dict.fromkeys([pt,en]+aliases)),'versions':versions}
 (repo/'scripts/reviewed-content'/('additional-clan-'+slug+'.json')).write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')

banu_disc='Feitiçaria de Sangue, Celeridade e Ofuscação. O aprendizado de rituais e poderes segue os requisitos próprios de cada opção.'
banu_disc_en='Blood Sorcery, Celerity and Obfuscate. Learning rituals and powers follows each option’s own requirements.'
banu_bane='Ao saciar pelo menos 1 Fome com Vitae de outro vampiro, faz um teste para resistir ao Frenesi de Fome com Dificuldade 2 + Gravidade da Perdição. Se falhar, tenta beber vorazmente Sangue vampírico, podendo chegar à Diablerie. O gatilho é saciar Fome com Vitae, não apenas a presença de outro vampiro.'
banu_bane_en='Slaking at least 1 Hunger with another vampire’s vitae triggers a hunger frenzy resistance test at Difficulty 2 + Bane Severity. Failure makes the vampire attempt to gorge on vampiric Blood, potentially reaching diablerie. The trigger is slaking Hunger with vitae, not merely another vampire’s presence.'
banu_comp='Julgamento: precisa punir alguém que transgrida seu código pessoal tomando seu sangue como vingança. Durante a cena, deve saciar ao menos 1 Fome de alguém, amigo ou inimigo, que aja contra uma Convicção sua. Caso contrário, sofre −3 dados em todas as rolagens até satisfazer a Compulsão ou a cena terminar. Se beber de outro vampiro, também aplica o teste de Frenesi da Perdição.'
banu_comp_en='Judgment: must punish someone transgressing the vampire’s personal code by taking blood as vengeance. During the scene, must slake at least 1 Hunger from someone, friend or foe, acting against one of the vampire’s Convictions. Otherwise suffers −3 dice on all rolls until the Compulsion is satisfied or the scene ends. Feeding on another vampire also triggers the Bane’s frenzy test.'
add('banu-haqim','Banu Haqim','Banu Haqim',['Filhos de Haqim','Children of Haqim'],[
 version('clan-banu-haqim-camarilla-v5','camarilla-v5',[(168,167),(169,168)],'Camarilla V5, pp. 167–168',banu_disc,banu_disc_en,banu_bane,banu_bane_en,banu_comp,banu_comp_en),
 version('clan-banu-haqim-players-guide-v5','players-guide-v5',[(19,17),(20,18)],'Player’s Guide V5, pp. 17–18',banu_disc,banu_disc_en,banu_bane,banu_bane_en,banu_comp,banu_comp_en,
 'As Convicções podem ser puramente pessoais; não precisam representar uma cultura mortal ou uma seita.',
 'Convictions may be purely personal; they need not represent a mortal culture or sect.')])

hecata_disc='Auspícios, Fortitude e Oblívio. A percepção sobrenatural, resistência e necromancia são as Disciplinas padrão do clã.'
hecata_disc_en='Auspex, Fortitude and Oblivion. Supernatural perception, endurance and necromancy are the clan’s standard Disciplines.'
hecata_bane='O Beijo causa agonia. Ao beber diretamente de uma vítima, só pode tomar goles prejudiciais que causem perda de sangue. Mortais relutantes e não contidos tentam escapar. Mesmo mortais coagidos ou dispostos precisam vencer Vigor + Determinação, Dificuldade 2 + Gravidade da Perdição, para não se debaterem de dor. Vampiros coagidos ou voluntários precisam resistir ao Frenesi de Terror com Dificuldade 3.'
hecata_bane_en='The Kiss causes agony. When drinking directly from a victim, may take only harmful drinks causing blood loss. Unwilling, unrestrained mortals try to escape. Even coerced or willing mortals must succeed at Stamina + Resolve, Difficulty 2 + Bane Severity, to avoid struggling against the pain. Coerced or willing vampire victims must resist terror frenzy at Difficulty 3.'
cults_comp='Morbidez: observa as pessoas em busca de doença, fragilidade e morte iminente. Sofre −3 dados nas outras rolagens até prever uma morte sem ajuda sobrenatural ou resolver a causa de uma morte local, ou até o fim da cena. As conclusões não precisam estar absolutamente corretas, mas devem ser possíveis.'
cults_comp_en='Morbidity: studies people for disease, frailty and impending death. Suffers −3 dice on other rolls until predicting a death without supernatural aid, solving the cause of a local death, or the scene ends. Conclusions need not be completely correct but must remain possible.'
guide_comp='Morbidez: precisa imediatamente mover algo da vida para a morte ou vice-versa. Sofre −2 dados em qualquer ação que não se dedique a encerrar ou ressuscitar algo. O alvo não precisa ser uma pessoa nem estar vivo: pode ser um objeto, uma ideia ou uma conversa. A Compulsão termina quando mata ou devolve algo à vida, literal ou figurativamente; este texto não impõe um término automático ao fim da cena.'
guide_comp_en='Morbidity: immediately needs to move something from life to death or vice versa. Suffers −2 dice on any action not dedicated to ending or resurrecting something. The subject need not be a person or alive: it may be an object, idea or conversation. The Compulsion ends after killing or returning something to life, literally or figuratively; this text does not impose an automatic end at scene’s close.'
different_pt='A Compulsão de Cultos e a do Guia têm gatilhos de resolução e penalidades diferentes. A versão selecionada da fonte é mantida; não são somadas nem substituídas automaticamente. Confirme com o Narrador qual fonte a crônica utiliza.'
different_en='The Cults and Player’s Guide Compulsions have different resolution conditions and penalties. The selected source version is preserved; they are not combined or automatically substituted. Confirm which source the chronicle uses with the Storyteller.'
blood_pt='Cultos permite, a critério do Narrador, substituir uma Disciplina por linhagem: Giovanni troca Auspícios por Dominação; Samedi troca Auspícios por Ofuscação; Lamiae troca Auspícios por Potência; Nagaraja troca Fortitude por Dominação. Isso pode impedir Amálgamas que dependam das Disciplinas padrão. Alternativamente, o Narrador pode oferecer uma Qualidade de 4 pontos para adquirir a Disciplina substituta como quarta Disciplina de Clã. Essas são opções dependentes do Narrador, não benefícios automáticos de todo Hecata.'
blood_en='Cults permits lineage-based substitutions at the Storyteller’s discretion: Giovanni replaces Auspex with Dominate; Samedi replaces Auspex with Obfuscate; Lamiae replaces Auspex with Potence; Nagaraja replaces Fortitude with Dominate. This may prevent Amalgams relying on the standard Disciplines. Alternatively, the Storyteller may offer a four-dot Merit adding the substitute as a fourth clan Discipline. These are Storyteller-dependent options, not automatic benefits for every Hecata.'
add('hecata','Hecata','Hecata',['Clã da Morte','Clan of Death'],[
 version('clan-hecata-cults-v5','cultos-deuses-sangue-v5',[(202,202),(203,203)],'Cultos dos Deuses de Sangue V5, pp. 202–203',hecata_disc,hecata_disc_en,hecata_bane,hecata_bane_en,cults_comp,cults_comp_en,different_pt+'\n\n'+blood_pt,different_en+'\n\n'+blood_en),
 version('clan-hecata-players-guide-v5','players-guide-v5',[(25,23),(26,24)],'Player’s Guide V5, pp. 23–24',hecata_disc,hecata_disc_en,hecata_bane,hecata_bane_en,guide_comp,guide_comp_en,different_pt+' Linhagens e loresheets têm regras próprias; a escolha do clã não concede seus benefícios automaticamente.',different_en+' Bloodlines and loresheets have their own rules; choosing the clan does not automatically grant their benefits.')])

ministry_disc='Ofuscação, Presença e Proteanismo. Ocultação, influência emocional e transformação corporal; a tradição do clã pode chamar Proteanismo de Serpentis.'
ministry_disc_en='Obfuscate, Presence and Protean. Concealment, emotional influence and bodily transformation; clan tradition may call Protean Serpentis.'
ministry_comp='Transgressão: sofre −2 dados em todas as paradas que não se relacionem a tentar alguém, incluindo a si mesmo, a quebrar um Princípio da Crônica ou uma Convicção pessoal. Precisa causar ao menos 1 Mácula com essa transgressão para encerrar a Compulsão.'
ministry_comp_en='Transgression: suffers −2 dice on all pools unrelated to enticing someone, including the vampire, to break a Chronicle Tenet or personal Conviction. Must cause at least 1 Stain through that transgression to end the Compulsion.'
add('ministry','Ministério','Ministry',['The Ministry','Setitas','Seguidores de Set','Followers of Set'],[
 version('clan-ministry-anarch-v5','anarch-v5',[(188,None),(189,None)],'Anarch V5, páginas do PDF 188–189',ministry_disc,ministry_disc_en,
 'A luz direta, natural ou artificial, faz o Ministro recuar. Sofre uma penalidade igual à Gravidade da Perdição em todas as paradas quando exposto à luz dirigida diretamente a ele. Também acrescenta a Gravidade da Perdição ao dano Agravado sofrido por luz solar.',
 'Direct light, natural or artificial, makes the Minister recoil. Suffers a penalty equal to Bane Severity on all pools when subjected to light directed straight at the vampire. Also adds Bane Severity to Aggravated damage from sunlight.',ministry_comp,ministry_comp_en),
 version('clan-ministry-players-guide-v5','players-guide-v5',[(37,35),(38,36)],'Player’s Guide V5, pp. 35–36',ministry_disc,ministry_disc_en,
 'Luz direta, natural ou artificial, faz o Ministro recuar. Sob luz brilhante apontada diretamente para ele, sofre uma penalidade igual à Gravidade da Perdição em todas as paradas. Também acrescenta a Gravidade da Perdição ao dano Agravado recebido da luz solar.',
 'Direct light, natural or artificial, makes the Minister recoil. Bright light directed straight at the vampire imposes a penalty equal to Bane Severity on all pools. Also adds Bane Severity to Aggravated damage taken from sunlight.',ministry_comp,ministry_comp_en)])
print('Three clans, six bilingual source-specific versions; original Hecata Compulsions preserved.')
